def epoch_loss(losses, sizes):
    count = sum(sizes)
    return sum(loss*n for loss,n in zip(losses,sizes))/count if count else None

def parameter_count(input_dim, layers):
    total = 0
    for output_dim in layers:
        total += (input_dim + 1) * output_dim
        input_dim = output_dim
    return total

def nonfinite_indices(values):
    from math import isfinite
    return [i for i,v in enumerate(values) if not isfinite(v)]

def train_step(w, x, y, lr):
    gradient = sum(2*(w*a-b)*a for a,b in zip(x,y)) / len(x)
    return w - lr*gradient
